<?php
declare(strict_types=1);

namespace Nelson\Resizer\Placeholder;

use Imagine\Exception\Exception as ImagineException;
use Imagine\Image\AbstractImagine;
use Imagine\Image\Box;
use Imagine\Image\Point;
use Nelson\Resizer\Dimensions;
use Nelson\Resizer\Exceptions\ResizerException;
use Nelson\Resizer\IResizer;
use Nelson\Resizer\Resizer;
use Nelson\Resizer\ResizerConfig;
use Nelson\Resizer\ResizerLinkGenerator;
use Nelson\Resizer\ResizerParamsParser;

/**
 * Creates placeholders from a tiny thumbnail generated by the resizer itself (crop, EXIF orientation,
 * the first frame of animations - all the same as the real thumbnail), cached like any thumbnail.
 *
 * get() is meant for rendering: it generates at most "placeholderBudget" new tiny thumbnails per request,
 * the other images get no placeholder until a next render, so a page with many new images is not slowed down.
 * warmUp() has no limit - call it when an image is uploaded.
 */
final class PlaceholderGenerator
{
	/** The longest side of the tiny thumbnail */
	public const int SIZE = 16;

	private const int QUALITY = 40;

	private AbstractImagine $imagine;
	private int $generated = 0;

	/** @var array<string, Placeholder|null> */
	private array $cache = [];


	public function __construct(
		private readonly IResizer $resizer,
		private readonly ResizerConfig $config,
	) {
		/** @var class-string<AbstractImagine> $library */
		$library = 'Imagine\\' . $this->config->getLibrary() . '\\Imagine';
		$this->imagine = new $library;
	}


	/**
	 * Placeholder of the thumbnail, null when it can't be created or the budget of this request is spent.
	 */
	public function get(string $file, ?string $params = null): ?Placeholder
	{
		return $this->create($file, $params, useBudget: true);
	}


	/**
	 * Generates the placeholder regardless of the budget, e.g. right after an upload.
	 */
	public function warmUp(string $file, ?string $params = null): ?Placeholder
	{
		return $this->create($file, $params, useBudget: false);
	}


	/**
	 * Params of the tiny thumbnail: the output dimensions scaled to SIZE, the same crop alignment.
	 */
	public static function getTinyParams(?string $params, Dimensions $output): ?string
	{
		try {
			$resizerParams = (new ResizerParamsParser($params ?? ResizerLinkGenerator::PARAMS_AUTO))->getParams();
		} catch (ResizerException) {
			return null;
		}

		$scale = min(1, self::SIZE / max($output->getWidth(), $output->getHeight()));
		$width = max(1, (int) round($output->getWidth() * $scale));
		$height = max(1, (int) round($output->getHeight() * $scale));

		$tiny = $resizerParams->isCrop()
			? $resizerParams->getHorizontal() . $width . 'x' . $resizerParams->getVertical() . $height
			: $width . 'x' . $height;

		return $tiny . ($resizerParams->getForceDimensions() ? '!' : '') . '-q' . self::QUALITY;
	}


	private function create(string $file, ?string $params, bool $useBudget): ?Placeholder
	{
		$key = $file . "\0" . $params;

		if (array_key_exists($key, $this->cache)) {
			return $this->cache[$key];
		}

		$output = $this->resizer->getOutputDimensions($file, $params);
		$tinyParams = $output === null ? null : self::getTinyParams($params, $output);

		if ($tinyParams === null) {
			return $this->cache[$key] = null;
		}

		// GIF: PNG, the first frame (an animated tiny WEBP is of no use)
		$format = !str_ends_with(strtolower($file), '.gif') && $this->config->isFormatSupportedByServer(Resizer::FORMAT_SUFFIX_WEBP)
			? Resizer::FORMAT_SUFFIX_WEBP
			: Resizer::FORMAT_SUFFIX_PNG;

		try {
			if (!$this->resizer->thumbnailExists($this->resizer->getThumbnailPath($file, $tinyParams, $format))) {
				if ($useBudget && $this->generated >= $this->config->getPlaceholderBudget()) {
					return null; // not cached, the budget may be raised by warmUp() calls in this request
				}

				$this->generated++;
			}

			$path = $this->resizer->process($file, $tinyParams, $format);
			$data = @file_get_contents($path);

			if ($data === false || $data === '') {
				return $this->cache[$key] = null;
			}

			$image = $this->imagine->open($path);
			$size = $image->getSize();
			$color = $image->resize(new Box(1, 1))->getColorAt(new Point(0, 0)); // the average
		} catch (ResizerException | ImagineException) {
			return $this->cache[$key] = null;
		}

		$hex = (string) $color;
		$alpha = $color->getAlpha();

		return $this->cache[$key] = new Placeholder(
			preg_match('~^#[0-9a-f]{6}$~i', $hex) === 1 ? strtolower($hex) : '#808080',
			'data:' . Resizer::MIME_TYPES[$format] . ';base64,' . base64_encode($data),
			new Dimensions(max(1, $size->getWidth()), max(1, $size->getHeight())),
			$alpha !== null && $alpha < 100,
		);
	}
}
